// TypeScript version
export function diffJson<T>(a: any, b: any): { added: string[], removed: string[], modified: string[] } {
  const added = new Set<string>();
  const removed = new Set<string>();
  const modified = [];

  // Merge keys from both objects
  const allKeys = new Set([...Object.keys(a), ...Object.keys(b)]);
  
  allKeys.forEach(key => {
    if (a.hasOwnProperty(key)) added.add(key);
    if (b.hasOwnProperty(key)) removed.add(key);
  });

  // Compare values
  for (const key of allKeys) {
    const aVal = a[key];
    const bVal = b[key];
    if (JSON.stringify(aVal) !== JSON.stringify(bVal)) {
      modified.push(key);
    }
  };

  return { added, removed, modified };
}

// Python version
def diff_json(a: dict, b: dict):
    added = set()
    removed = set()
    modifications = []

    for key in set(a.keys()) | set(b.keys()):
        if key not in a:
            removed.add(key)
        elif key not in b:
            added.add(key)
        else:
            if (a[key] != b[key]):
                modifications.append(key)

    return {'added': list(added), 'removed': list(removed), 'modified': modifications}


